// src/util/error.ts
import { Schema } from "effect";

class NamedError2 extends Error {
  static hasName(error, name) {
    return typeof error === "object" && error !== null && "name" in error && error.name === name;
  }
  static create(name, data) {
    return NamedError2.createSchemaClass(name, Schema.isSchema(data) ? data : Schema.Struct(data));
  }
  static createSchemaClass(name, data) {
    const schema = Schema.Struct({
      name: Schema.Literal(name),
      data
    }).annotate({ identifier: name });
    const result = class extends NamedError2 {
      data;
      static Schema = schema;
      static EffectSchema = schema;
      static tag = name;
      name = name;
      constructor(data, options) {
        super(name, options);
        this.data = data;
        this.name = name;
      }
      static isInstance(input) {
        return NamedError2.hasName(input, name);
      }
      schema() {
        return schema;
      }
      toObject() {
        return {
          name,
          data: this.data
        };
      }
    };
    Object.defineProperty(result, "name", { value: name });
    return result;
  }
  static Unknown = NamedError2.create("UnknownError", {
    message: Schema.String,
    ref: Schema.optional(Schema.String)
  });
}

export { NamedError2 };
